 private function deliveryRecipients(int$id):array{if(($this->notificationConfig['test_mode']??false)===true){$email=strtolower(trim((string)($this->notificationConfig['test_email']??'')));return filter_var($email,FILTER_VALIDATE_EMAIL)?['emails'=>[$email],'warning'=>'']:['emails'=>[],'warning'=>'Test-mode notification email is invalid.'];}$emails=array_values(array_unique(array_filter(array_map('strtolower',$this->r->recipients($id)),fn($v)=>filter_var($v,FILTER_VALIDATE_EMAIL))));return['emails'=>$emails,'warning'=>$emails===[]?'No current Manager or Assistant Manager has a valid email.':''];}
